function extractGroupUrlsFromContent(fileContent) {
    let urls = [];
    const text = String(fileContent || '').trim();
    if (!text) return [];

    if (text.startsWith('{') || text.startsWith('[')) {
        try {
            const parsed = JSON.parse(text);
            function findUrls(obj) {
                if (!obj) return;
                if (typeof obj === 'string') {
                    const norm = normalizeFacebookUrl(obj, 'group');
                    if (norm) urls.push(norm);
                    else if (obj.includes('/groups/')) {
                        const match = obj.match(/https?:\/\/[^\s"',]+/);
                        if (match) {
                            const normMatch = normalizeFacebookUrl(match[0], 'group');
                            if (normMatch) urls.push(normMatch);
                        }
                    }
                } else if (Array.isArray(obj)) {
                    obj.forEach(item => findUrls(item));
                } else if (typeof obj === 'object') {
                    const possibleUrl = obj.url || obj.link || obj.groupUrl || obj.href || obj.grupo || obj.group;
                    if (possibleUrl) {
                        findUrls(possibleUrl);
                    } else {
                        Object.values(obj).forEach(val => findUrls(val));
                    }
                }
            }
            findUrls(parsed);
        } catch (e) {}
    }

    if (urls.length === 0) {
        const matches = text.match(/https?:\/\/(?:www\.|m\.)?facebook\.com\/groups\/[^\s"',\n]+/gi) || [];
        matches.forEach(m => {
            const norm = normalizeFacebookUrl(m, 'group');
            if (norm) urls.push(norm);
        });
    }

    return Array.from(new Set(urls));
}


